   * Processes a stream event and checks for loop conditions.
   *
   * @param event - The stream event to process
   * @returns A {@link LoopDetectionResult}. `count` is `0` when no loop is
   *   detected, `1` on the first detection for the current prompt, and `2` (or
   *   higher) when a loop is detected again after a previous detection was
   *   cleared via {@link clearDetection}.
   */
  addAndCheck(event: ServerGeminiStreamEvent): LoopDetectionResult {
    if (this.disabledForSession || this.config.getDisableLoopDetection()) {
      return { count: 0 };
    }

    if (this.loopDetected) {
      // A detection is already active and has not been cleared yet; keep
      // returning the same result rather than re-counting it as a new strike.
      return this.activeDetection ?? { count: this.detectionCount };
    }

    let detection: { type: LoopType; detail: string } | null = null;
    switch (event.type) {
      case GeminiEventType.ToolCallRequest:
        // content chanting only happens in one single stream, reset if there
        // is a tool call in between
        this.resetContentTracking();
        if (this.checkToolCallLoop(event.value)) {
          detection = {
            type: LoopType.CONSECUTIVE_IDENTICAL_TOOL_CALLS,
            detail: `The tool "${event.value.name}" was called repeatedly with the same arguments without making progress.`,
          };
        }
        break;
      case GeminiEventType.Content:
        if (this.checkContentLoop(event.value)) {
          detection = {
            type: LoopType.CHANTING_IDENTICAL_SENTENCES,
            detail:
              'The response repeated the same content multiple times without making progress.',
          };
        }
        break;
      default:
        break;
    }

    if (detection) {
      this.loopDetected = true;
      this.detectionCount++;
      this.activeDetection = {
        count: this.detectionCount,
        type: detection.type,
        detail: detection.detail,
      };
      return this.activeDetection;
    }

    return { count: 0 };
  }

  /**
   * Clears the active loop detection state so the agent can attempt to
   * self-correct, while preserving the cumulative strike count so a subsequent
   * detection escalates.
